import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"地泽临","description":"周易折中 - 地泽临","frontmatter":{"title":"地泽临","description":"周易折中 - 地泽临"},"headers":[],"relativePath":"zh/classics/zhezhong/025.md","filePath":"zh/classics/zhezhong/025.md"}'),h={name:"zh/classics/zhezhong/025.md"};function n(d,a,p,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="地泽临" tabindex="-1">地泽临 <a class="header-anchor" href="#地泽临" aria-label="Permalink to “地泽临”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>临序卦：有事而后可大，故受之以临。临者，大也。蛊者事也，有事则可大矣，故受之以临也。韩康伯云：“可大之业，由事而生。二阳方长而盛大，故为临也。”为卦泽上有地，泽上之地岸也，与水相际，临近乎水，故为临。天下之物密近相临者，莫若地与水，故地上有水则为比，泽上有地则为临也。临者，临民临事，凡所临皆是。在卦取自上临下，临民之义。</p><p>临：元亨利贞，至于八月有凶</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>临进而凌逼于物也。二阳浸长，以逼于阴，故为临。十二月之卦也。又其为卦，下兑说、上坤顺，九二以刚居中，上应六五，故占者大亨而利于正。然至于八月，当有凶也。八月，谓自复卦一阳之月，至于遁卦二阴之月，阴长阳遁之时也。或曰八月谓夏正八月，于卦为观，亦临之反对也。又因占而戒之。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>以卦才言也。临之道如卦之才，则大亨而正也。二阳方长于下，阳道向盛之时，圣人豫为之戒曰：阳虽方长，至于八月，则其道消矣，是有凶也。大率圣人为戒，必于方盛之时。方盛而虑衰，则可以防其满极，而图其永久。若既衰而后戒，则无及矣。自古天下安治，未有久而不乱者，盖不能戒于盛也。方其盛而不知戒，故狃安富则骄侈生，乐舒肆则纲纪坏，忘祸乱则衅孽萌，是以浸淫不知乱之至也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>张子曰：临言有凶者，易之于爻变。阳至二便为之戒，未过中已戒，犹履霜坚冰之义。及泰之三曰：“无平不陂，无往不复。”过中之戒也。</li></ul><p>张子曰：临言有凶者，易之于爻变。阳至二便为之戒，未过中已戒，犹履霜坚冰之义。及泰之三曰：“无平不陂，无往不复。”过中之戒也。</p><ul><li>朱子语类问临：不特上临下之谓临，凡进而逼近者皆谓之临。否曰：“然此是二阳自下而进，上则凡相逼近者皆为临也。”</li></ul><p>朱子语类问临：不特上临下之谓临，凡进而逼近者皆谓之临。否曰：“然此是二阳自下而进，上则凡相逼近者皆为临也。”</p><ul><li>程氏迥曰：阳极于九而少阴生于八，阴之义配月；阴极于六而少阳复于七，阳之义配日。</li></ul><p>程氏迥曰：阳极于九而少阴生于八，阴之义配月；阴极于六而少阳复于七，阳之义配日。</p><ul><li>王氏应麟曰：临所谓八月，其说有三：一云自丑至申为否；一云自子至未为遁；一云自寅至酉为观。本义兼取遁、观二说。复所谓七日，其说有三：一谓卦气起中孚六日七分之后为复；一谓过坤六位至复为七日；一谓自五月姤一阴生至十一月一阳生。本义取自姤至复之说。</li></ul><p>王氏应麟曰：临所谓八月，其说有三：一云自丑至申为否；一云自子至未为遁；一云自寅至酉为观。本义兼取遁、观二说。复所谓七日，其说有三：一谓卦气起中孚六日七分之后为复；一谓过坤六位至复为七日；一谓自五月姤一阴生至十一月一阳生。本义取自姤至复之说。</p><ul><li>胡氏炳文曰：诸家临字训近训大，只见上临下，不见刚临柔之意。本义依如临深渊之临，谓进而迫于渊。此所谓临者，刚进而迫于柔也。盖复者，阴之极而阳初来也；临者，二阳皆来而迫于阴也。故复亨而临大亨。复不言利贞者，复是初阳之萌，无有不善；临则二阳浸盛，易至放肆，故戒之也。</li></ul><p>胡氏炳文曰：诸家临字训近训大，只见上临下，不见刚临柔之意。本义依如临深渊之临，谓进而迫于渊。此所谓临者，刚进而迫于柔也。盖复者，阴之极而阳初来也；临者，二阳皆来而迫于阴也。故复亨而临大亨。复不言利贞者，复是初阳之萌，无有不善；临则二阳浸盛，易至放肆，故戒之也。</p><p>象曰：泽上有地，临；君子以教思无穷，容保民无疆</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>地临于泽上，临下也。二者皆临下之事。教之无穷者兑也（泽），容之无疆者坤也（地）。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽之上有地，泽岸也，水之际也。物之相临与含容无若水之在地，故泽上有地为临也。君子观亲临之象，则教思无穷，亲临于民则有教导之意思也，无穷至诚无斁也。观含容之象，则有容保民之心无疆，广大无疆限也。含容有广大之意，故为无穷无疆之义。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：相临之道莫若悦顺，不恃威制，得物之诚，故物无违也。是以君子教思无穷，容保民无疆。</p></li><li><p>刘氏牧曰 ：岸高于泽，俯临之也。</p></li><li><p>胡氏炳文曰 ：不徒曰教而曰教思，其意思如兑泽之深；不徒曰保民而曰容保民，其度量如坤土之大。</p></li><li><p>俞氏琰曰 ：临有二义，以爻之阴阳言，则为大临小；以象之地泽言，则为上临下。</p></li><li><p>蔡氏清曰 ：教思谓其一假教育成就人底意思也。教人以善谓之忠，味忠之一字，方见此之所谓教思者。又曰劳之来之，匡之直之，辅之翼之，使自得之，又从而振德之。此可见君子教思之无穷。民吾同胞，以至鳏寡孤独皆吾弟兄之颠连无告者也，必使皆乐其乐而利其利，可见君子之容保民无疆也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>临者大也。泽上有地，泽之盛满将与地平，大之义也。教思无穷，容保无疆，盖言王泽之盛大，所以沦浃之深而渐被之广者。</p><p>彖曰：临，刚浸而长</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏应麟曰：《阴符经》云：“天地之道，浸。”故阴阳胜。愚尝读《易》之临卦曰“刚浸而长”，遁卦曰“浸而长”也。自临而长为泰，自遁而长为否。浸者，渐也。圣人之戒深矣。</p></li><li><p>张氏清子曰：自复一阳生，积而至临，则二阳长矣。故曰“刚浸而长”。遁者，临之反也。临《彖》曰“刚浸而长”，遁《彖》不曰“柔浸而长”，而止曰“小利贞”。浸而长，《易》不为小人谋也。</p></li></ul><p>说而顺，刚中而应</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>又以卦德卦体言卦之善。</p><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>刚浸而长，则阳道方亨；有说顺之德，则人心和附；刚中得应，则上下交而志同。此其所以德泽及于天下，而足以有临也。此亦如泰之取义，兼交泰与消长两意见，正道之盛大。故夫子释之曰：“临者，大也。”若但以临为陵逼小人之义，则于卦爻之辞多有所难通者。</p><p>大亨以正，天之道也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>当刚长之时，又有此善，故其占如此也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>浸，渐也。二阳长于下而渐进也。下兑上坤，和说而顺也。刚得中道而有应助，是以能大亨而得正，合天之道。刚正而和顺，天之道也。化育之功所以不息者，刚正和顺而已。以此临人、临事、临天下，莫不大亨而得正也。兑为说，说乃和也。《夬·彖》云：“决而和。”</p><p>至于八月有凶，消不久也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>言虽天运之当然，然君子宜知所戒。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>临，二阳生，阳方渐盛之时，故圣人为之戒云：阳虽方长，然至于八月则消而凶矣。八月谓阳生之八月，阳始生于复，自复至遁凡八月，自建子至建未也。二阴长而阳消矣，故云“消不久也”。在阴阳之气言之，则消长如循环，不可易也；以人事言之，则阳为君子，阴为小人。方君子道长之时，圣人为之诫，使知极则有凶之理，而虞备之，常不至于满极，则无凶也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：阳长之卦，每卦皆应“八月有凶”。但此卦名临，是盛大之义，故于此卦特戒之耳。若以类言之，则阳长之卦至其终末皆有凶也。</p></li><li><p>陆氏振奇曰：日为阳象，月为阴象。八，少阴之数；七，少阳之数。故言阴来之期曰八月，言阳来之期曰七日。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>八月七日之说者多凿，陆氏之说最为得之。盖阳数穷于九，则退而生少阴之八；阴数穷于六，则进而生少阳之七。七八者，阴阳始生之数也。若拘拘于卦气月候之配，则震、既济之七日与夫三日、三年、十年之类，皆多不可通者矣。</p><p>初九：咸临，贞吉</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>卦唯二阳遍临四阴，故二爻皆有咸临之象。初九刚而得正，故其占为贞吉。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>咸，感也。阳长之时，感动于阴，四应于初，感之者也比它卦相应尤重。四近君之位，初得正位，与四感应，是以正道为当位所信任，得行其志，获乎上而得行其正道，是以吉也。它卦初、上爻不言得位、失位，盖初终之义为重也。临则以初得位居正为重。凡言贞吉，有既正且吉者，有得正则吉者，有贞固守之则吉者，各随其事也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏舜臣曰：山泽通气，故山上有泽，其卦为咸。而泽上有地，初二爻亦谓之咸者，阴阳之气相感也。</li></ul><p>象曰：咸临贞吉，志行正也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>所谓贞吉，九之志在于行正也。以九居阳，又应四之正，其志正也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰愼曰：有守正有行正，临初正与屯同。</li></ul><p>九二：咸临，吉，无不利</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>刚得中而势上进，故其占吉而无不利也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二方阳长而渐盛，感动于六五中顺之君，其交之亲，故见信任，得行其志，所临吉而无不利也。吉者，已然如是故吉也；无不利者，将然于所施为，无所不利也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏清曰：初九以刚得正而吉，九二以刚中而吉。刚中则贞，无待于言也。刚中，最易之所善。</li></ul><p>象曰：咸临吉无不利，未顺命也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>未详</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>未者，非遽之辞。孟子或问劝齐伐燕有诸，曰“未也”。又云“仲子所食之粟，伯夷之所树与？抑亦盗跖之所树与？是未可知也”。史记侯嬴曰“人固未易知”。古人用字之意皆如此，今人大率用对己字，故意似异然实不殊也。九二与五感应以临下，盖以刚德之长而又得中，至诚相感，非由顺上之命也。是以吉而无不利。五顺体而二说体，又阴阳相应，故象特明其非由说顺也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>君子道长，天之命也。然命不于常，故彖言“八月有凶”，而传言“消不久”。君子处此，惟知持盈若虚，所谓“大亨以正天之道者”，则顺道而非顺命矣。以二为刚长之主，即卦主也，故特发此义以与彖意相应。凡天之命消长焉而已，方其长也，则不顺命不受命，知盈不可久而进不可恃也；及其消也，则志不舍命，知物不可穷而往之必复也。易之大义尽在于斯。</p><p>六三：甘临，无攸利，既忧之，无咎</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>阴柔不中正而居下之上，为以甘说临人之象。其占固无所利，然能忧而改之，则无咎也。勉人迁善为教深矣。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三居下之上，临人者也。阴柔而说，体又处不中正，以甘说临人者，在上而以甘说临下，失德之甚，无所利也。兑性既说，又乘二阳之上，阳方长而上进，故不安而益甘。既知危惧而忧之，若能持谦守正，至诚以自处，则无咎也。邪说由己，能忧而改之，复何咎乎？</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：乐而受之谓之甘。</p></li><li><p>胡氏炳文曰：彖唯取刚临柔，爻则初二外皆上临下。三兑体在二阳之上，为以甘说临人之象。节九五以中正为甘则吉，此以不中不正为甘，故无攸利。忧者说之反，能忧而改则无咎矣。案临卦本取势之盛大为义，因其势之盛大，又欲其德业之盛大，是此卦彖爻之意也。初二以德感人，故曰咸。以德感人者，盖以盛大为忧而未尝乐也。六三说主德不中正，以势为乐，故曰甘临。夫恣情于势位，则何利之有哉？然说极则有忧之理，既忧则知势位之非乐，而咎不长矣。此爻与节三“不节之嗟”正相似，皆兑体也。</p></li></ul><p>象曰：甘临位不当也，既忧之咎不长也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>阴柔之人处不中正而居下之上，复乘二阳，是处不当位也。既能知惧而忧之，则必强勉自改，故其过咎不长也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏简曰：六三不中不正，处不当位，虽甘说此位，亦安足以有临乎？能知而忧之，强勉自改，则过咎不长也。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>三之爻位不当，而四之爻位当，故其德有善否。然三之所处位高势盛，不可甘也而甘之，此其所以为不当也。四之所处与下相亲最切至也，而能至焉，此其所以为当也。是为借爻位之当不当以明所处位之当不当，易之例也。</p><p>六四：至临，无咎</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>处得其位，下应初九，相临之至，宜无咎者也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四居上之下，与下体相比，是切临于下，临之至也。临道尚近，故以比为至。四居正位，而下应于刚阳之初，处近君之位，守正而任贤，以亲临于下，是以无咎，所处当也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰：四以上临下，其与下体最相亲，故曰至临。以言上下二体莫亲于此也。</li></ul><p>象曰：至临无咎，位当也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>居近君之位，为得其任。以阴处四，为得其正。与初相应，为下贤，所以无咎。盖由位之当也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰：其位在上下之际，临之切至也。凡上之临下，惟患其远而不相通。四既近于下，其所处之位至当，是以无咎。</li></ul><p>六五：知临，大君之宜，吉</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>以柔居中，下应九二，不自用而任人，乃知之事，而大君之宜吉之道也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五以柔中顺体居尊位，而下应于二刚中之臣，是能倚任于二，不劳治以知临下者也。夫以一人之身临乎天下之广，若区区自任，岂能周于万事？故自任其知者，适足为不知。唯能取天下之善，任天下之聪明，则无所不周。是不自任其知，则其知大矣。五顺应于九二刚中之贤，任之以临下，乃己以明知临天下，大君之所宜也，其吉可知。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰：《中庸》曰：“唯天下至圣为能聪明睿知，足以有临也。”故知临为大君之宜。六五以柔中之德任九二刚中之贤，不自用其知而兼众知，为知之大，是宜为君而获吉也。</p></li><li><p>胡氏炳文曰：临是以己临人，五虚中下应九二，不任己而任人，所以为知，所以为大君之宜。</p></li></ul><p>象曰：大君之宜，行中之谓也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>君臣道合，盖以气类相求。五有中德，故能倚任刚中之贤，得大君之宜，成知临之功。盖由行其中德也。人君之于贤才，非道同德合岂能用也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>沈氏该曰：能以其知行中者也。</li></ul><p>上六：敦临，吉，无咎</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>居卦之上，处临之终，敦厚于临，吉而无咎之道也。故其象占如此。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上六坤之极，顺之至也，而居临之终，敦厚于临也。与初二虽非正应，然大率阴求于阳，又其至顺，故志在从乎二阳，尊而应卑，高而从下，尊贤取善，敦厚之至也。故曰敦临，所以吉而无咎。阴柔在上，非能临者，宜有咎也。以其敦厚于顺，刚是以吉而无咎。六居临之终而不取极义，临无过极，故止为厚义。上无位之地，止以在上言。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：上六敦临，自是积累至极处，有敦笃之义。艮上九亦谓之敦艮，复上六爻不好了，所以只于五爻谓之敦复。</p></li><li><p>杨氏启新曰：处临之终，有厚道焉。教思无穷，容保无疆者也。如是，则德厚而物无不载，道久而化无不成。</p></li></ul><p>象曰：敦临之吉，志在内也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>志在内，应乎初与二也。志顺刚阳而敦笃，其吉可知也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏振渊曰：志在内即万物一体之意，所以能敦。若将天下国家置在度外，虽有些小德泽，终是浅薄。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>此“志在内”当与泰初“志在外”反观。同是天下国家也，自初言之则为外，自上言之则为内。伊尹躬耕而自任以天下之重，可谓志在外矣；尧舜耄期倦勤而念不忘民，可谓志在内矣。</p>',130)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
